// Seeds the demo persona (profile 1) with the ESCO skills the CV reader extracted from her sample CV
// (db/seed/persona_esco.json, generated by a real intake run, not hand-picked). Source = 'cv'.
import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import { projectRoot, type Db } from "../lib/db.ts";

export async function seedPersonaEsco(t: Db) {
  const f = path.join(projectRoot, "db", "seed", "persona_esco.json");
  if (!existsSync(f)) return;
  const { skills } = JSON.parse(readFileSync(f, "utf8"));
  for (const s of skills)
    await t.query("insert into profile_esco_skills(profile_id, skill_id, source) values (1, $1, 'cv') on conflict do nothing", [s.escoId]);
}
